contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address recipient, uint256 amount) public {
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 balanceBefore = c.balanceOf(recipient); if (__ESBMC_reverted()) return;

        bool minted;
        c.mintToken(recipient, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            minted = false;
        } else {
            minted = true;
        }

        uint256 supplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 balanceAfter = c.balanceOf(recipient); if (__ESBMC_reverted()) return;

        assert(minted
            ? (supplyAfter == supplyBefore + amount && balanceAfter == balanceBefore + amount)
            : (supplyAfter == supplyBefore && balanceAfter == balanceBefore));
    }
}

