pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address recipient, uint256 amount) internal {
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        uint256 balanceBefore;
        try c.balanceOf(recipient) returns (uint256 __r) { balanceBefore = __r; } catch { return; }
        bool minted;
        try c.mintToken(recipient, amount) {
            minted = true;
        } catch {
            minted = false;
        }
        uint256 supplyAfter;
        try c.totalSupply() returns (uint256 __r) { supplyAfter = __r; } catch { return; }
        uint256 balanceAfter;
        try c.balanceOf(recipient) returns (uint256 __r) { balanceAfter = __r; } catch { return; }
        assertTrue(minted
            ? (supplyAfter == supplyBefore + amount && balanceAfter == balanceBefore + amount)
            : (supplyAfter == supplyBefore && balanceAfter == balanceBefore));
    }

    function testFuzz_run(address recipient, uint256 amount) public {
        vm.assume(recipient.code.length == 0 && uint160(recipient) > 0xffff && recipient != address(this) && recipient != address(c) && recipient != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && recipient != 0x000000000000000000636F6e736F6c652e6c6f67 && recipient != 0x4e59b44847b379578588920cA78FbF26c0B4956C && recipient != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(recipient, amount);
    }

    receive() external payable {}
}
